package com.guillermomolina.protos.cli;
import com.guillermomolina.protos.runtime.*; import java.util.*;
final class ProtosValueRenderer { String render(Object v){return r(v,new IdentityHashMap<>(),0);} private String r(Object v,IdentityHashMap<Object,Boolean>s,int d){if(v==ProtosNullValue.INSTANCE)return"null";if(v==ProtosBooleanValue.TRUE)return"true";if(v==ProtosBooleanValue.FALSE)return"false";if(v instanceof ProtosIntegerValue x)return x.value().toString();if(v instanceof ProtosFloatValue x)return Double.toString(x.value());if(v instanceof ProtosFixedIntegerValue x)return x.value().toString();if(v instanceof ProtosStringValue x)return "\""+x.value().replace("\\","\\\\").replace("\"","\\\"")+"\"";if(d>7)return"...";if(s.put(v,true)!=null)return"<cycle>";try{if(v instanceof ProtosArrayValue x)return "["+x.indexedSnapshot().stream().map(e->r(e,s,d+1)).reduce((a,b)->a+", "+b).orElse("")+"]";if(v instanceof ProtosMapValue x){StringJoiner j=new StringJoiner(", ","{","}");for(var e:x.keyedSnapshot())j.add(r(e.key(),s,d+1)+": "+r(e.value(),s,d+1));return j.toString();}if(v instanceof ProtosIdentityMapValue x){StringJoiner j=new StringJoiner(", ","IdentityMap{","}");for(var e:x.keyedSnapshot())j.add(r(e.key(),s,d+1)+": "+r(e.value(),s,d+1));return j.toString();}return v instanceof ProtosObjectValue?"<object>":"<value>";}finally{s.remove(v);}}}
